const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');

// Gerenciador de Ataques: valida contra o formato de ataques/schema.json (RF05, RF06, RNF07)
const ehJson = (h) => String((h || {})['content-type'] || '').toLowerCase().includes('application/json');
const req = $('POST /ataques').first().json;
if (!ehJson(req.headers)) return [{ json: { valido: false, status: 400, corpo: { erros: ['Envie o corpo em JSON (Content-Type: application/json).'] } } }];
const corpo = req.body;
const existentes = new Set($('Nomes existentes').first().json.nomes || []);
const erros = [];
const CAMPOS = ['nome', 'estrategia', 'descricao', 'mensagens'];
const lista = Array.isArray(corpo) ? corpo : [corpo];
if (corpo === null || corpo === undefined || typeof corpo !== 'object' || (Array.isArray(corpo) && corpo.length === 0)) {
  return [{ json: { valido: false, status: 400, corpo: { erros: ['O corpo deve ser um ataque (objeto JSON) ou uma lista não vazia de ataques.'] } } }];
}
const vistos = new Set();
const ataques = [];
lista.forEach((a, i) => {
  const p = Array.isArray(corpo) ? `[${i}].` : '';
  if (a === null || typeof a !== 'object' || Array.isArray(a)) { erros.push(`${p.replace(/\.$/, '') || 'ataque'}: deve ser um objeto.`); return; }
  for (const k of Object.keys(a)) if (!CAMPOS.includes(k)) erros.push(`${p}${k}: campo desconhecido (permitidos: ${CAMPOS.join(', ')}).`);
  if (typeof a.nome !== 'string' || !/^[a-z0-9-]{1,80}$/.test(a.nome)) {
    erros.push(`${p}nome: obrigatório; use só letras minúsculas, dígitos e hífen, até 80 caracteres.`);
  } else if (vistos.has(a.nome)) {
    erros.push(`${p}nome: "${a.nome}" aparece mais de uma vez no arquivo.`);
  } else if (existentes.has(a.nome)) {
    erros.push(`${p}nome: já existe um ataque chamado "${a.nome}".`);
  }
  if (typeof a.nome === 'string') vistos.add(a.nome);
  if (typeof a.estrategia !== 'string' || !/^[a-z0-9_]{1,60}$/.test(a.estrategia)) {
    erros.push(`${p}estrategia: obrigatória; use só letras minúsculas, dígitos e sublinhado (ex.: pedido_direto).`);
  }
  if (a.descricao !== undefined && a.descricao !== null && typeof a.descricao !== 'string') {
    erros.push(`${p}descricao: deve ser texto.`);
  }
  if (!Array.isArray(a.mensagens) || a.mensagens.length === 0) {
    erros.push(`${p}mensagens: obrigatória; lista com pelo menos uma mensagem (1 = turno único, mais de 1 = multi-turno).`);
  } else {
    a.mensagens.forEach((m, j) => {
      if (typeof m !== 'string' || m.trim() === '') erros.push(`${p}mensagens[${j}]: deve ser um texto não vazio.`);
    });
  }
  ataques.push({ nome: a.nome, estrategia: a.estrategia, descricao: a.descricao ?? null, mensagens: a.mensagens });
});
if (erros.length) return [{ json: { valido: false, status: 400, corpo: { erros } } }];
return [{ json: { valido: true, b64: b64(ataques) } }];
